const phases=[
 ['Definir el proyecto y el resultado','Elabora el contrato del proyecto: destinatario, problema, entrada, salida y límites. Utiliza la muestra y distingue el resultado de aprendizaje de los servicios que todavía no están conectados.','BRIEF.md'],
 ['Preparar el entorno y los materiales','Abre el espacio concreto de esta herramienta, coloca los archivos de entrada y comprueba los requisitos antes de modificar el proyecto. Registra cómo volver a abrirlo.','PREPARACION.md'],
 ['Entender datos, archivos y decisiones','Relaciona cada campo de entrada con el resultado y localiza la pieza que lo transforma. Conserva tipos, identificadores y reglas de ausencia para poder diagnosticar después.','CONTRATO.md'],
 ['Escribir el encargo y las pruebas de referencia','Prepara el encargo completo con los datos del caso. Escribe lo que debe ocurrir antes de ejecutar y separa un caso normal de una variación que pueda revelar un error.','ENCARGO-Y-PRUEBAS.md'],
 ['Construir la primera versión completa','Realiza el recorrido de principio a fin usando la configuración específica. Conserva las salidas intermedias y abre el resultado real en el lugar donde lo utilizará el destinatario.','PRIMERA-VERSION.md'],
 ['Mejorar una decisión con una comparación','Conserva la versión anterior y aplica la mejora propuesta para esta herramienta. Compara con la misma muestra y vuelve a comprobar los comportamientos que ya funcionaban.','REVISION-01.md'],
 ['Diagnosticar y corregir un fallo','Introduce un fallo reversible en una copia o utiliza un error observado. Registra entrada, acción, esperado y observado; comprueba una hipótesis antes de cambiar varias piezas.','DIAGNOSTICO.md'],
 ['Comprobar variaciones y casos incompletos','Realiza las pruebas del contrato con datos ausentes, repetidos o límites pertinentes al proyecto. Define la respuesta esperada de cada caso antes de ejecutar.','EVIDENCIAS.md'],
 ['Preparar una entrega que pueda recuperarse','Exporta o guarda el material que necesita el destinatario. Abre una copia separada utilizando únicamente las instrucciones y comprueba permisos, dependencias y contenido.','ENTREGA.md'],
 ['Aplicarlo a un proyecto real y mantenerlo','Adapta los datos y las conexiones de forma explícita. Mide ensayos pequeños, documenta límites y asigna quién revisa errores y mantiene el procedimiento.','OPERACION.md'],
]

const nativePromptKinds=new Set(['text','web','code','research'])
function where(s){if(['image','video','audio','slides'].includes(s.kind))return 'En un asistente de texto para preparar el brief, el prompt visual o el guion. En la herramienta creativa introduce únicamente el prompt de generación o guion que resulte; no pegues allí todo este encargo de tutoría. Revisa el resultado generado y compáralo con el brief.';if(s.kind==='dictation')return 'En un asistente de texto externo, solo para preparar o revisar el guion. En Wispr Flow se dicta el guion; no se pega este encargo como si fuera un chatbot.';return nativePromptKinds.has(s.kind)?`En el asistente de ${s.id} cuando la función esté disponible; para un editor sin chat, utiliza un asistente de texto y aplica el resultado en la herramienta.`:'En un asistente de texto o programación. La configuración, fórmula o código resultante se aplica después en la herramienta; no pegues el encargo en una consola SQL, un campo de datos o un terminal.'}

function authoredProjectLessons(tool,en=false) {
 const s=specs[tool.id];if(!s)throw new Error('Missing project curriculum: '+tool.id)
 const files=starterFiles(s.kind),input=JSON.stringify(requests,null,2)
 if(en)return englishProjectLessons(tool,s,files)
 return phases.map(([title,focus,artifact],index)=>{
  const phaseAction=index===1?s.open:index===4?s.build:index===5?s.improve:index===8||index===9?s.deliver:focus
  const fullPrompt=`Estoy trabajando en ${tool.label} dentro de un programa de aprendizaje aplicado. Mi proyecto es «${s.title}».\n\nUNIDAD Y RESULTADO\nUnidad ${index+1}: ${title}. ${focus}\nObjetivo completo: ${s.goal}\nEntrega de esta unidad: ${artifact}.\n\nENTORNO Y MATERIALES\n${s.open}\nMi versión o entorno concreto es [VERSIÓN O ENTORNO]. Mi nivel es [NIVEL]. Los archivos del paquete son: ${Object.keys(files).join(', ')}. Si necesitas inspeccionar un archivo para editarlo, pídeme ese archivo o léelo si ya está disponible; no inventes su contenido.\n\nMUESTRA DE DATOS\n${input}\nLos datos son ficticios. Conserva los identificadores, no conviertas una solicitud en una plaza confirmada y no atribuyas a la herramienta acceso a servicios que no estén conectados. Para proyectos visuales o de comunicación, estos datos sirven como contexto del caso; aplica el brief específico y no los fuerces a aparecer en la pieza.\n\nTRABAJO CONCRETO DE ESTA UNIDAD\n${phaseAction}\nImplementación de referencia: ${s.build}\nResultado que deberá comprobarse: ${s.expected}\nNo me entregues solo una lista de recomendaciones. Desarrolla el trabajo con estos datos y produce el contenido de ${artifact}. Explica primero la decisión central de esta unidad y después cada paso con su ubicación, el dato que recibe, la configuración o contenido que debo introducir y la salida que debería observar. Si corresponde escribir código, una fórmula, un esquema o un guion, proporciona la pieza completa necesaria para ese paso, con una explicación de sus partes. Distingue el material ya disponible del que debo crear.\n\nREVISIÓN Y CONTINUIDAD\nRelaciona cada conclusión con la muestra o con una comprobación. No afirmes que un archivo se guardó, que una prueba pasó o que una API respondió si no has observado esa acción. Señala qué datos debo completar en mi entorno y cómo verificar que se han aplicado. Conserva las reglas y los archivos que ya funcionan. Incluye una prueba normal, una variación pertinente y el resultado esperado de ambas. Si esta unidad no ejecuta todavía el proyecto completo, delimita su entrega y explica qué utilizaré en la siguiente.\n\nCierra con el contenido final del documento, los pasos que he de realizar en la herramienta y una lista corta de evidencias. Para llevarlo a un uso real considera este requisito específico: ${s.deliver} Si una capacidad depende de mi versión o cuenta, indica cómo comprobarla en la documentación o interfaz en vez de asegurar que existe.`
  const repair=`Revisa mi trabajo de la unidad «${title}» en ${tool.label}.\nProyecto: ${s.title}. Objetivo: ${s.goal}\nResultado esperado del recorrido: ${s.expected}\nEntrega de esta unidad: ${artifact}.\nTe proporciono la entrada que utilicé: [ENTRADA REAL ANONIMIZADA]. Esta es mi salida o contenido actual: [RESULTADO]. Estas son las comprobaciones que he realizado: [EVIDENCIAS].\nCompara lo observado con el contrato de la unidad. Distingue un error factual, un problema de configuración, una diferencia de presentación y una parte que todavía no está ejecutada. No sustituyas datos ausentes por suposiciones. Para cada diferencia relevante indica el fragmento o paso exacto, el motivo y la corrección mínima. Conserva todo lo que sí cumple la referencia.\nDespués proporciona una versión corregida del fragmento o una configuración concreta, y explica cómo comprobarla con la misma muestra. Incluye una prueba que revelaría el defecto antes de corregirlo y que debería pasar después. Si se produjo una escritura externa con respuesta incierta, explica cómo consultar el destino antes de repetir. No presentes una propuesta de corrección como si ya se hubiera aplicado. Termina con los resultados que puedo dar por comprobados y los que siguen pendientes de evidencia.`
  return {title:`${String(index+1).padStart(2,'0')} · ${title}`,outcome:`${s.title}: ${focus}`,context:[s.goal,`En esta unidad producirás ${artifact}. El recorrido completo utiliza un caso de estudio y termina con una entrega utilizable y sus comprobaciones. ${phaseAction}`,`Cómo funciona la parte específica de ${tool.label}: ${s.build}`,`La referencia final que protege el trabajo es: ${s.expected} La extensión de la explicación no sustituye observar ese resultado; conserva la muestra, la configuración y las evidencias para poder retomarlo.`],prerequisites:[{name:'Espacio de trabajo de la herramienta',instruction:s.open,check:'Puedes identificar el proyecto, localizar sus archivos y volver a abrirlo sin depender de la conversación.'},{name:'Paquete y muestra del proyecto',instruction:'Descarga el paquete de esta herramienta y abre README.md y reference.md. Conserva los originales. Para empezar una unidad intermedia, revisa también las entregas anteriores; no necesitas repetir una preparación ya comprobada.',check:'Los archivos de la lista de materiales están presentes y puedes explicar cuál es fuente, cuál es código o plantilla y cuál es resultado.'}],inputs:[{field:'project',example:s.title,rule:'El objetivo y el destinatario determinan las decisiones, no la cantidad de funciones del producto.'},{field:'source',example:'requests.csv / requests.json / reference.md',rule:'Muestra ficticia de tres solicitudes. No se inventan precios, plazas ni resultados externos.'},{field:'deliverable',example:artifact,rule:'Conserva la entrega de esta unidad con su versión y la evidencia que realmente hayas observado.'}],steps:[{title:'Situar el trabajo de esta unidad',instruction:focus+' Lee la referencia completa y anota qué parte vas a producir ahora y qué seguirá pendiente.',configuration:`Proyecto: ${s.title}\nEntrega: ${artifact}\nObjetivo: ${s.goal}\nReferencia: ${s.expected}`,expected:`Existe un encabezado de ${artifact} con objetivo, muestra y alcance.`,why:'Definir el alcance evita repetir el mismo ejercicio sin saber qué decisión nueva se aprende en cada unidad.'},{title:`Realizar la operación en ${tool.label}`,instruction:phaseAction,configuration:index===4&&['code','node','docker','python','colab'].includes(s.kind)?(s.kind==='python'||s.kind==='colab'?'python summarize.py requests.csv':s.kind==='docker'?'docker compose up --build':'npm test\nnpm start'):undefined,expected:index===4?s.expected:'El documento contiene la decisión y los pasos concretos de la unidad, con referencias a los archivos o controles utilizados.',why:`Esta operación está vinculada al proyecto de ${s.title}, no a una recomendación general de utilizar la herramienta.`},{title:'Utilizar el encargo y contrastar la respuesta',instruction:'Copia el prompt completo, sustituye NIVEL y VERSIÓN O ENTORNO y aporta los archivos que necesite. Comprueba el contenido que propone antes de aplicarlo. Si el producto no recibe prompts, usa el asistente indicado y aplica después la configuración en la herramienta.',expected:'La respuesta resuelve la muestra y produce el contenido de la entrega. No se limita a pedirte que «configures correctamente» sin mostrar cómo.',why:'El prompt aporta contexto, contrato y criterios; la revisión posterior comprueba que la respuesta se ajusta al caso.'},{title:'Probar una variación y documentar el efecto',instruction:index===5?s.improve:'Utiliza una copia de la muestra. Cambia un dato relevante, una condición o un elemento del brief y escribe el resultado esperado antes de repetir. Conserva además el caso original. '+s.improve,expected:'Puedes explicar qué decisión cambió, qué resultado produjo y qué comportamiento se mantuvo.',why:'La variación comprueba comprensión y evita que una única muestra memorizada parezca una implementación general.'},{title:'Cerrar la unidad con una entrega revisable',instruction:`Completa ${artifact} con fuente, procedimiento, configuración, esperado, observado, variación y límites. Abre el archivo sin el chat y corrige cualquier referencia que dependa de recordar lo hablado.`,configuration:`# ${artifact}\n## Objetivo\n## Fuente y versión\n## Decisión de esta unidad\n## Pasos y configuración\n## Resultado esperado\n## Resultado observado y evidencia\n## Variación comprobada\n## Límites y siguiente paso`,expected:'Otra persona puede interpretar el estado y continuar con la siguiente unidad sin dar por hechos resultados no observados.',why:'La documentación forma parte del aprendizaje y de la entrega del proyecto.'}],prompts:[{title:'Encargo desarrollado de la unidad',where:where(s),replace:'Completa NIVEL y VERSIÓN O ENTORNO. La muestra está incluida; sustitúyela por datos propios solo cuando hayas verificado el ensayo.',text:fullPrompt,expected:`La respuesta contiene el trabajo concreto de ${artifact}, su explicación y las comprobaciones relacionadas con ${s.expected}`,followUp:`Has descrito el trabajo pero no has producido la entrega. Desarrolla ahora ${artifact} con la muestra proporcionada. Para cada paso muestra el contenido o configuración y lo que debería observar. Si falta un dato real, identifícalo y explica cómo obtenerlo sin inventarlo.`},{title:'Revisión y corrección con evidencia',where:where(s),replace:'Sustituye ENTRADA, RESULTADO y EVIDENCIAS por el trabajo real de esta unidad. No incluyas credenciales.',text:repair,expected:'Una revisión que señala diferencias concretas, conserva lo correcto y proporciona una corrección comprobable.',followUp:'La corrección no ha resuelto la diferencia. Este es el resultado después de aplicarla: [NUEVA EVIDENCIA]. Revisa la hipótesis anterior, explica qué la confirma o descarta y propone una comprobación distinta antes de modificar más partes.'}],files:[{name:`${tool.id}-project.zip`,purpose:'Paquete con muestra, referencia, materiales de arranque y README específico. Los archivos ejecutables se identifican en las instrucciones; las piezas creativas deben producirse en su herramienta.',url:`/project-assets/tools/${tool.id}.zip`},{name:artifact,purpose:'Plantilla de la entrega de esta unidad. Completa la columna observada únicamente después de revisar o ejecutar.',content:`# ${s.title}\nUnidad ${index+1}: ${title}\n\nObjetivo: ${focus}\n\nFuente: requests.csv y reference.md\nReferencia del proyecto: ${s.expected}\n\nDecisión y motivo:\nConfiguración utilizada:\nResultado observado:\nEvidencia:\nVariación:\nLímites:\nSiguiente paso:\n`}],tests:[{name:'Referencia del proyecto',input:'Muestra original del paquete; en proyectos creativos, brief y guion de referencia.',expected:s.expected,inspect:'El archivo, pantalla, consulta o respuesta real que describe la implementación.'},{name:'Variación pertinente',input:s.improve,expected:'Se cumple la mejora prevista y se conserva el comportamiento original que no forma parte del cambio.',inspect:'Comparación de versiones usando la misma muestra y una segunda entrada.'},{name:'Dato o requisito ausente',input:'Retira en una copia un campo necesario, un archivo de entrada o una parte obligatoria del brief.',expected:'La ausencia se comunica y no se sustituye por un dato inventado ni una acción supuestamente realizada.',inspect:'Mensaje de error, salida de revisión o lista de requisitos pendientes.'}],troubleshooting:[{symptom:'La respuesta es extensa pero no me dice qué introducir',cause:'El asistente ha descrito categorías de trabajo sin resolver la muestra.',fix:'Utiliza el prompt de corrección y pide el contenido de un único paso: archivo, campo o configuración, con entrada y salida. Compruébalo antes de continuar.'},{symptom:'El resultado de la herramienta no coincide con el ejemplo',cause:'Puede diferir la fuente, el tipo de dato, el entorno o una condición del contrato.',fix:'Conserva entrada y salida del primer paso que difiere. Revisa el archivo o configuración concretos y utiliza la misma muestra para comprobar la corrección.'},{symptom:'Funciona en mi sesión, pero otra persona no puede usarlo',cause:'La entrega puede depender de archivos locales, permisos, cuentas o almacenamiento de tu navegador.',fix:s.deliver}],production:[s.deliver,'Sustituye la muestra por un caso propio permitido y registra qué reglas cambian. No amplíes volumen ni conexiones sin volver a comprobar esas diferencias.','Realiza tres ensayos y mide preparación, ejecución y revisión. Conserva errores y tiempo observado; no conviertas una estimación inicial en una promesa de ahorro.','Asigna quién mantiene datos, archivos y conexiones, dónde se registran errores y cómo se recupera una versión conocida. Documenta el siguiente cambio como una decisión revisable.'],sources:[{title:`Referencia técnica del proyecto de ${tool.label}`,url:s.source}]}
 })
}

export function projectReadme(s) {
 const command=['code','node'].includes(s.kind)?'npm test\nnpm start':s.kind==='docker'?'docker compose up --build':['python','colab'].includes(s.kind)?'python summarize.py requests.csv':['web','react','tailwind','vscode','vercel'].includes(s.kind)?'Abre index.html en un navegador. Lee la limitación de almacenamiento local antes de adaptar el proyecto.':'Abre requests.csv, reference.md y el brief. Crea el resultado en la herramienta siguiendo su guía.'
 return `# ${s.title}\n\nCaso de estudio ficticio de Aula Norte.\n\n## Objetivo\n${s.goal}\n\n## Preparación\n${s.open}\n\n## Empezar\n${command}\n\n## Construcción\n${s.build}\n\n## Resultado de referencia\n${s.expected}\n\n## Mejora guiada\n${s.improve}\n\n## Entrega y límites\n${s.deliver}\n\n## Documentación\n${s.source}\n`
}

export function projectLessons(tool,en=false) { const spec={...specs[tool.id],...(en?englishProfiles[tool.id]:{})}; return authoredProjectLessons(tool,en).map((manual,index)=>learningSequence(plainToolLesson(manual,tool,spec,index,en),tool,spec,index,en)) }
